const MARKET_SAVE: &str = "";

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digits"))
        .collect()
}

/// The test data of "clan" with a separation rate and the first year of the window.
fn homes_data(separation: f64, fertile_from: f64) -> Data {
    let (mut calibration, genome_map) =
        common::death_files(0.02, None, common::repository_diseases());
    let mut demography = common::demography();
    common::window_fertility(&mut calibration, &mut demography, 0.25);
    calibration["fertility"]["window"]["from"]["value"] = serde_json::json!(fertile_from);
    demography["values"]["core:separation_rate"]["value"] = serde_json::json!(separation);
    Data::new(common::definitions_with(demography, calibration, genome_map).expect("definitions"))
        .expect("checked")
}

/// The test data of "market": the repository's life course data with the search at 1.
fn market_data() -> Data {
    let (calibration, genome_map) = common::files();
    let mut demography = common::demography();
    demography["values"]["core:market_search_height_female"]["value"] = serde_json::json!(1.0);
    Data::new(common::definitions_with(demography, calibration, genome_map).expect("definitions"))
        .expect("checked")
}

fn load(save: &str, data: Data) -> World {
    World::load(&hex(save), data).expect("loads").0
}

fn pedigree_json(world: &World) -> String {
    serde_json::to_string(&world.pedigree()).expect("json")
}

fn sim(n: u64) -> SimId {
    SimId::try_from(n).expect("valid")
}

/// Each export against the reference.
#[test]
fn the_pedigree_is_the_references() {
    let cases = [
        (
            "step after the separation",
            STEP_AFTER_SEPARATION_SAVE,
            homes_data(0.05, 16.0),
            STEP_AFTER_SEPARATION_PEDIGREE,
        ),
        (
            "step at its end",
            STEP_END_SAVE,
            homes_data(0.05, 16.0),
            STEP_END_PEDIGREE,
        ),
        (
            "kin at its end",
            KIN_END_SAVE,
            homes_data(0.025, 18.0),
            KIN_END_PEDIGREE,
        ),
        (
            "neither at its end",
            NEITHER_END_SAVE,
            homes_data(0.01, 18.0),
            NEITHER_END_PEDIGREE,
        ),
        (
            "afflicted in year 38",
            AFFLICTED_YEAR_38_SAVE,
            common::only_diseases_data(),
            AFFLICTED_YEAR_38_PEDIGREE,
        ),
        (
            "afflicted switched off, year 39",
            AFFLICTED_OFF_YEAR_39_SAVE,
            common::only_diseases_data(),
            AFFLICTED_OFF_YEAR_39_PEDIGREE,
        ),
        (
            "loci after the start",
            LOCI_AFTER_START_SAVE,
            common::data(),
            LOCI_AFTER_START_PEDIGREE,
        ),
    ];
    for (name, save, data, expected) in cases {
        assert_eq!(pedigree_json(&load(save, data)), expected, "{name}");
    }
}

/// An override that switches the diseases off, stamped at the clock, acts from the next
/// second on: at the clock the diseases still show as before.
#[test]
fn an_override_shows_from_the_second_after_its_stamp() {
    let mut world = load(AFFLICTED_YEAR_38_SAVE, common::only_diseases_data());
    world
        .submit(Input::ForkOverride(ForkOverride {
            changes: vec![ParamChange::HereditaryDiseases(false)],
        }))
        .expect("accepted");
    world.take_log();
    assert_eq!(pedigree_json(&world), AFFLICTED_YEAR_38_PEDIGREE);
}

/// φ of known pairs (parent and child, siblings, half siblings, first cousins, unrelated
/// founders, a person with itself) and `None` for an unknown ID, on the saves of "step" at
/// its end and "market" at the end of year 39.
#[test]
fn kinship_of_known_pairs() {
    let step: [(u64, u64, Option<f64>); 7] = [
        (2, 8, Some(0.25)),
        (10, 11, Some(0.25)),
        (8, 9, Some(0.125)),
        (1, 3, Some(0.0)),
        (1, 1, Some(0.5)),
        (8, 8, Some(0.5)),
        (14, 8, None),
    ];
    let market: [(u64, u64, Option<f64>); 7] = [
        (1, 12, Some(0.25)),
        (13, 14, Some(0.25)),
        (24, 26, Some(0.0625)),
        (1, 2, Some(0.0)),
        (1, 1, Some(0.5)),
        (24, 24, Some(0.5)),
        (39, 1, None),
    ];
    for (world, pairs) in [
        (load(STEP_END_SAVE, homes_data(0.05, 16.0)), step),
        (load(MARKET_SAVE, market_data()), market),
    ] {
        for (a, b, phi) in pairs {
            assert_eq!(world.state().kinship(sim(a), sim(b)), phi, "{a} and {b}");
            assert_eq!(world.state().kinship(sim(b), sim(a)), phi, "{b} and {a}");
        }
    }
}
